mapper.select:
SELECT COUNT(*)
  FROM TB_GM01M01 A
 WHERE A.CO_CD = #{coCd, jdbcType=VARCHAR}

   AND A.OUT_DT >= #{outDtFrom, jdbcType=VARCHAR}


   AND A.OUT_DT <= #{outDtTo, jdbcType=VARCHAR}


   AND A.USB_CD = #{usbCd, jdbcType=VARCHAR}


   AND A.IN_DT IS NULL


   AND A.IN_DT IS NOT NULL


   AND SUBSTR(A.OUT_DEPT_ID, 1, 5) = SUBSTR(#{outDeptId, jdbcType=VARCHAR}, 1, 5)


   AND A.OWN_USER_ID = #{ownUserId, jdbcType=VARCHAR}


   AND A.VEND_CLNT_CD = #{vendClntCd, jdbcType=VARCHAR}


   AND UPPER(A.SALES_CD) LIKE '%' || UPPER(#{salesCd, jdbcType=VARCHAR}) || '%'


   AND UPPER(A.RMK) LIKE '%' || UPPER(#{rmk, jdbcType=VARCHAR}) || '%'

SELECT * FROM ( SELECT A.CO_CD , A.MNG_NO , A.OUT_DT , A.USB_CD , FN_CM05M01_CD_TO_NM(A.USB_CD) AS USB_NM , NVL(A.OUT_DEPT_ID, (SELECT CODE_ETC FROM TB_CM05M01 WHERE CODE_ID = A.USB_CD AND ROWNUM = 1)) AS OUT_DEPT_ID , NVL( (SELECT T4.DEPT_NM FROM TB_CM05M01 T5 LEFT JOIN TB_CM04M01 T4 ON T5.CODE_ETC = T4.DEPT_ID WHERE T5.CODE_ID = A.USB_CD AND ROWNUM = 1), NVL(A.OUT_DEPT_NM, (SELECT DEPT_NM FROM TB_CM04M01 WHERE DEPT_ID = A.OUT_DEPT_ID AND ROWNUM = 1)) ) AS OUT_DEPT_NM , A.OWN_DEPT_ID , A.OWN_DEPT_NM , A.OWN_USER_ID , A.OWN_USER_NM , A.VEND_CLNT_CD , A.VEND_CLNT_NM , A.VEND_USER_NM , A.SALES_CD , A.CLNT_PJT , A.CLNT_PJT_NM , A.EQP_NM , A.RMK , A.IN_DT , A.IN_USER_ID , NVL(FN_CM06M01_ID_TO_NM(A.IN_USER_ID), A.IN_USER_NM) AS IN_USER_NM , A.IN_RMK , TO_CHAR(A.IN_DTTM, 'YYYY-MM-DD HH24:MI') AS IN_DTTM , CASE WHEN A.IN_DT IS NOT NULL THEN 'IN' ELSE 'OUT' END AS STS_CD , A.CREAT_ID , CASE WHEN A.UDT_ID IS NOT NULL THEN NVL(FN_CM06M01_ID_TO_NM(A.UDT_ID), A.UDT_ID) ELSE NVL(FN_CM06M01_ID_TO_NM(A.CREAT_ID), A.CREAT_ID) END AS CREAT_NM , CASE WHEN A.UDT_DTTM IS NOT NULL THEN TO_CHAR(A.UDT_DTTM, 'YYYY-MM-DD HH24:MI') ELSE TO_CHAR(A.CREAT_DTTM, 'YYYY-MM-DD HH24:MI') END AS CREAT_DTTM , ROW_NUMBER() OVER (ORDER BY CASE WHEN A.IN_DT IS NULL THEN 0 ELSE 1 END, A.OUT_DT DESC, A.MNG_NO DESC) AS RNUM FROM TB_GM01M01 A WHERE A.CO_CD = #{coCd, jdbcType=VARCHAR}
AND A.OUT_DT >= #{outDtFrom, jdbcType=VARCHAR}
AND A.OUT_DT <= #{outDtTo, jdbcType=VARCHAR}
AND A.USB_CD = #{usbCd, jdbcType=VARCHAR}
AND A.IN_DT IS NULL
AND A.IN_DT IS NOT NULL
AND SUBSTR(A.OUT_DEPT_ID, 1, 5) = SUBSTR(#{outDeptId, jdbcType=VARCHAR}, 1, 5)
AND A.OWN_USER_ID = #{ownUserId, jdbcType=VARCHAR}
AND A.VEND_CLNT_CD = #{vendClntCd, jdbcType=VARCHAR}
AND UPPER(A.SALES_CD) LIKE '%' || UPPER(#{salesCd, jdbcType=VARCHAR}) || '%'
AND UPPER(A.RMK) LIKE '%' || UPPER(#{rmk, jdbcType=VARCHAR}) || '%'
) WHERE RNUM BETWEEN #{firstIndex, jdbcType=INTEGER} AND #{lastIndex, jdbcType=INTEGER}

mapper.update:
UPDATE TB_GM01M01
   SET OUT_DT       = #{outDt, jdbcType=VARCHAR}
     , USB_CD       = #{usbCd, jdbcType=VARCHAR}
     , OUT_DEPT_ID  = NVL(#{outDeptId, jdbcType=VARCHAR}, (SELECT CODE_ETC FROM TB_CM05M01 WHERE CODE_ID = #{usbCd, jdbcType=VARCHAR} AND ROWNUM = 1))
     , OUT_DEPT_NM  = NVL(#{outDeptNm, jdbcType=VARCHAR}, (SELECT DEPT_NM FROM TB_CM04M01 WHERE DEPT_ID = (SELECT CODE_ETC FROM TB_CM05M01 WHERE CODE_ID = #{usbCd, jdbcType=VARCHAR} AND ROWNUM = 1) AND ROWNUM = 1))
     , OWN_DEPT_ID  = #{ownDeptId, jdbcType=VARCHAR}
     , OWN_DEPT_NM  = #{ownDeptNm, jdbcType=VARCHAR}
     , OWN_USER_ID  = #{ownUserId, jdbcType=VARCHAR}
     , OWN_USER_NM  = #{ownUserNm, jdbcType=VARCHAR}
     , VEND_CLNT_CD = #{vendClntCd, jdbcType=VARCHAR}
     , VEND_CLNT_NM = #{vendClntNm, jdbcType=VARCHAR}
     , VEND_USER_NM = #{vendUserNm, jdbcType=VARCHAR}
     , SALES_CD     = #{salesCd, jdbcType=VARCHAR}
     , CLNT_PJT     = #{clntPjt, jdbcType=VARCHAR}
     , CLNT_PJT_NM   = #{clntPjtNm, jdbcType=VARCHAR}
     , EQP_NM       = #{eqpNm, jdbcType=VARCHAR}
     , RMK          = #{rmk, jdbcType=VARCHAR}
     , UDT_ID       = #{userId, jdbcType=VARCHAR}
     , UDT_DTTM     = SYSDATE
     , UDT_PGM      = #{pgmId, jdbcType=VARCHAR}
 WHERE CO_CD  = #{coCd, jdbcType=VARCHAR}
   AND MNG_NO = #{mngNo, jdbcType=VARCHAR}

UPDATE TB_GM01M01
   SET IN_DT      = #{inDt, jdbcType=VARCHAR}
     , IN_USER_ID = #{inUserId, jdbcType=VARCHAR}
     , IN_USER_NM = #{inUserNm, jdbcType=VARCHAR}
     , IN_RMK     = #{inRmk, jdbcType=VARCHAR}
     , IN_DTTM    = SYSDATE
     , UDT_ID     = #{userId, jdbcType=VARCHAR}
     , UDT_DTTM   = SYSDATE
     , UDT_PGM    = #{pgmId, jdbcType=VARCHAR}
 WHERE CO_CD  = #{coCd, jdbcType=VARCHAR}
   AND MNG_NO = #{mngNo, jdbcType=VARCHAR}

UPDATE TB_GM01M01
   SET IN_DT      = NULL
     , IN_USER_ID = NULL
     , IN_USER_NM = NULL
     , IN_RMK     = NULL
     , IN_DTTM    = NULL
     , UDT_ID     = #{userId, jdbcType=VARCHAR}
     , UDT_DTTM   = SYSDATE
     , UDT_PGM    = #{pgmId, jdbcType=VARCHAR}
 WHERE CO_CD  = #{coCd, jdbcType=VARCHAR}
   AND MNG_NO = #{mngNo, jdbcType=VARCHAR}

mapper.delete:
DELETE FROM TB_GM01M01
 WHERE CO_CD  = #{coCd, jdbcType=VARCHAR}
   AND MNG_NO = #{mngNo, jdbcType=VARCHAR}
